"""Dependency-free static assets for the Cockpit single-page interface."""

INDEX_HTML = r'''<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>NEXUS SEED Cockpit</title>
  <link rel="stylesheet" href="/cockpit/styles.css">
</head>
<body>
  <div class="shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">N</span><div><strong>NEXUS SEED</strong><small>HUMAN COCKPIT</small></div></div>
      <nav id="navigation" aria-label="Cockpit navigation">
        <button class="nav-item active" data-view="overview"><span>◫</span>Overview</button>
        <button class="nav-item" data-view="knowledge"><span>◉</span>World</button>
        <button class="nav-item" data-view="activity"><span>↳</span>Activity</button>
        <button class="nav-item" data-view="orchestrator"><span>◈</span>Projects</button>
        <button class="nav-item" data-view="system"><span>⋯</span>System</button>
      </nav>
      <div class="sidebar-foot">
        <div class="live-dot"><i></i><span id="sidebar-runtime">CONNECTING</span></div>
        <small id="last-update">Waiting for snapshot</small>
      </div>
    </aside>
    <section class="workspace">
      <header class="topbar">
        <div><p class="eyebrow" id="view-eyebrow">CURRENT SITUATION</p><h1 id="view-title">Overview</h1></div>
        <div class="top-actions">
          <div class="health-pill"><i></i><span id="runtime-status">Connecting</span></div>
          <button class="icon-button" id="refresh" title="Refresh">↻</button>
        </div>
      </header>
      <main id="app" aria-live="polite"><div class="loading"><span></span><p>Compiling current context…</p></div></main>
    </section>
  </div>

  <dialog id="auth-dialog">
    <form method="dialog" id="auth-form" class="dialog-card">
      <p class="eyebrow">SECURE CONNECTION</p><h2>Cockpitへ接続</h2>
      <p>NEXUS_SEED_WEBHOOK_TOKENを入力してください。トークンはこのタブ内だけに保持されます。</p>
      <label>Access token<input id="auth-token" type="password" autocomplete="off" required></label>
      <div class="dialog-actions"><button class="button primary" value="default">Connect</button></div>
      <p class="form-error" id="auth-error"></p>
    </form>
  </dialog>
  <div id="toast" role="status"></div>
  <script src="/cockpit/app.js" defer></script>
</body>
</html>'''


STYLES_CSS = r'''
:root{--bg:#071019;--panel:#0c1722;--panel-2:#101e2b;--line:#20303d;--text:#e8f0f4;--muted:#8497a6;--accent:#55e6b5;--accent-2:#6da8ff;--warn:#f3bf62;--danger:#ff7f7f;--ok:#64e1a9;--radius:16px;--shadow:0 20px 60px rgba(0,0,0,.25)}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}button{color:inherit}.shell{display:grid;grid-template-columns:232px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;padding:24px 16px 18px;background:#08131d;border-right:1px solid #182733;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:12px;padding:0 8px 28px}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,var(--accent),#2a9779);color:#052017;font-weight:900;box-shadow:0 0 28px rgba(85,230,181,.18)}.brand strong{display:block;font-size:13px;letter-spacing:.08em}.brand small{display:block;margin-top:3px;color:var(--muted);font-size:9px;letter-spacing:.18em}nav{display:grid;gap:5px}.nav-item{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;padding:11px 12px;border-radius:10px;color:#93a5b2;text-align:left;cursor:pointer;transition:.18s}.nav-item span{width:18px;color:#627785;font-size:17px;text-align:center}.nav-item b{margin-left:auto;min-width:19px;padding:2px 6px;border-radius:12px;background:#513131;color:#ffaaaa;font-size:10px;text-align:center}.nav-item:hover{background:#0e1d29;color:#dfe9ef}.nav-item.active{background:#122831;color:var(--accent)}.nav-item.active span{color:var(--accent)}.sidebar-foot{margin-top:auto;padding:16px 10px 4px;border-top:1px solid var(--line)}.sidebar-foot small{display:block;margin-top:7px;color:#587080;font-size:10px}.live-dot{display:flex;align-items:center;gap:8px;color:#9db0bd;font-size:10px;font-weight:700;letter-spacing:.12em}.live-dot i,.health-pill i{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 12px var(--accent)}.workspace{min-width:0}.topbar{min-height:94px;padding:23px 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #172632;background:rgba(7,16,25,.86);backdrop-filter:blur(16px);position:sticky;top:0;z-index:5}.eyebrow{margin:0 0 5px;color:#668091;font-size:9px;font-weight:800;letter-spacing:.2em}.topbar h1{margin:0;font-size:23px;letter-spacing:-.02em}.top-actions{display:flex;align-items:center;gap:10px}.health-pill{display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid #244135;border-radius:999px;background:#0c201b;color:#a6d8c4;font-size:11px}.button,.icon-button{border:1px solid var(--line);border-radius:9px;background:#12212d;padding:9px 13px;cursor:pointer;transition:.18s}.button:hover,.icon-button:hover{border-color:#47606f;transform:translateY(-1px)}.button.primary{border-color:#33866d;background:#154b3c;color:#c9ffed;font-weight:700}.button.danger{background:#3b2025;border-color:#74353f;color:#ffc0c7}.button.small{padding:6px 9px;font-size:11px}.icon-button{width:38px;height:38px;padding:0;font-size:18px}main{padding:28px 34px 60px;max-width:1540px;margin:0 auto}.loading{height:55vh;display:grid;place-content:center;text-align:center;color:var(--muted)}.loading span{width:30px;height:30px;margin:auto;border:2px solid #263947;border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.grid{display:grid;gap:16px}.metrics{grid-template-columns:repeat(6,minmax(120px,1fr));margin-bottom:18px}.metric{padding:17px 18px;border:1px solid var(--line);border-radius:var(--radius);background:linear-gradient(145deg,#0e1a25,#0b1620)}.metric .label{display:flex;align-items:center;justify-content:space-between;color:#718797;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.metric strong{display:block;margin-top:13px;font-size:27px;letter-spacing:-.04em}.metric small{color:#5f7585}.metric .tone-error{color:var(--danger)}.metric .tone-warning{color:var(--warn)}.focus-card{position:relative;overflow:hidden;min-height:150px;padding:25px 27px;margin-bottom:18px;border:1px solid #275044;border-radius:20px;background:radial-gradient(circle at 90% 20%,rgba(85,230,181,.12),transparent 34%),linear-gradient(140deg,#10251f,#0b1821)}.focus-card:before{content:"";position:absolute;left:0;top:24px;bottom:24px;width:3px;background:var(--accent);box-shadow:0 0 18px var(--accent)}.focus-card h2{max-width:850px;margin:16px 0 10px;font-size:25px;font-weight:580;line-height:1.3}.focus-meta{display:flex;gap:10px;align-items:center;color:#86a295;font-size:11px}.section{margin-top:27px}.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:12px}.section-head h2{margin:0;font-size:15px}.section-head p{margin:0;color:var(--muted);font-size:11px}.two-col{grid-template-columns:minmax(0,1.15fr) minmax(320px,.85fr)}.three-col{grid-template-columns:repeat(3,minmax(0,1fr))}.panel{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);box-shadow:var(--shadow)}.panel-pad{padding:18px}.attention-list,.stack{display:grid;gap:9px}.attention-item{display:grid;grid-template-columns:9px minmax(0,1fr) auto;gap:13px;align-items:start;padding:14px;border:1px solid #263543;border-radius:12px;background:#0d1924}.attention-item>.signal{width:8px;height:8px;margin-top:6px;border-radius:50%;background:var(--warn);box-shadow:0 0 10px rgba(243,191,98,.25)}.attention-item.error>.signal{background:var(--danger)}.attention-item h3,.card h3{margin:0 0 4px;font-size:13px}.attention-item p,.card p{margin:0;color:var(--muted);font-size:11px;line-height:1.5}.actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.empty{padding:28px;text-align:center;color:var(--muted);border:1px dashed #2a3a46;border-radius:12px}.empty strong{display:block;margin-bottom:5px;color:#b5c3cc}.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:11px}.card{padding:16px;border:1px solid var(--line);border-radius:13px;background:var(--panel)}.card-top{display:flex;justify-content:space-between;gap:10px;align-items:start}.card .meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px;color:#6f8493;font-size:10px}.badge{display:inline-flex;align-items:center;padding:3px 7px;border:1px solid #315064;border-radius:999px;background:#102432;color:#98c3dd;font-size:9px;font-weight:800;letter-spacing:.05em}.badge.ok,.badge.ACTIVE,.badge.COMPLETED,.badge.SATISFIED,.badge.HEALTHY,.badge.CONFIRMED{border-color:#285c4d;background:#102c25;color:#78d9b6}.badge.warn,.badge.WAITING,.badge.PAUSED,.badge.REVIEW,.badge.INFERRED{border-color:#655332;background:#302617;color:#e7bd70}.badge.error,.badge.FAILED,.badge.BLOCKED,.badge.BLOCKED_CAPABILITY,.badge.BLOCKED_PROVIDER,.badge.BLOCKED_PLAN,.badge.UNAVAILABLE{border-color:#6d3940;background:#321c22;color:#f1959f}.badge.OBSERVED{border-color:#3e5574;background:#16243a;color:#8db7ee}.timeline{position:relative;display:grid;gap:12px}.activity-card{position:relative;padding:18px 18px 15px 26px;border:1px solid var(--line);border-radius:14px;background:var(--panel)}.activity-card:before{content:"";position:absolute;left:10px;top:23px;width:6px;height:6px;border-radius:50%;background:var(--accent-2);box-shadow:0 0 12px var(--accent-2)}.activity-card .result{float:right}.activity-steps{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:13px 0;color:#9badb8;font-size:10px}.activity-steps span:not(:last-child):after{content:"→";margin-left:6px;color:#3c5362}details{margin-top:12px;border-top:1px solid #1d2d39;padding-top:10px}summary{cursor:pointer;color:#7992a2;font-size:10px}.raw{overflow:auto;max-height:340px;margin:10px 0 0;padding:12px;border-radius:9px;background:#071019;color:#9db1bf;font:10px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap}.being-hero{grid-template-columns:1fr 1fr;margin-bottom:17px}.identity{font-size:20px;margin:10px 0}.list{margin:10px 0 0;padding-left:18px;color:#a7b6c0;font-size:11px;line-height:1.7}.claim{padding:10px 0;border-bottom:1px solid #1b2a35}.claim:last-child{border:0}.claim-value{margin-top:5px;color:#aebbc4;font-size:11px}.capabilities{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.tabs{display:flex;gap:6px;margin-bottom:13px}.tab{padding:7px 11px;border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--muted);cursor:pointer}.tab.active{background:#16302a;color:var(--accent);border-color:#2d6554}.provider-health{width:10px;height:10px;border-radius:50%;background:var(--ok);box-shadow:0 0 10px rgba(100,225,169,.3)}.provider-health.bad{background:var(--danger)}dialog{border:0;padding:0;background:transparent;color:var(--text)}dialog::backdrop{background:rgba(2,7,11,.82);backdrop-filter:blur(5px)}.dialog-card{width:min(430px,calc(100vw - 32px));padding:25px;border:1px solid #2d4453;border-radius:17px;background:#0d1a25;box-shadow:var(--shadow)}.dialog-card h2{margin:5px 0 10px}.dialog-card p{color:var(--muted);font-size:12px;line-height:1.5}.dialog-card label{display:grid;gap:7px;margin-top:18px;color:#91a5b3;font-size:11px}.dialog-card input{width:100%;padding:11px;border:1px solid #304653;border-radius:9px;background:#07121b;color:var(--text)}.dialog-actions{display:flex;justify-content:flex-end;margin-top:18px}.form-error{color:var(--danger)!important}#toast{position:fixed;right:24px;bottom:24px;z-index:30;max-width:420px;padding:13px 16px;border:1px solid #32614f;border-radius:11px;background:#102b23;box-shadow:var(--shadow);color:#c8f4e3;font-size:12px;opacity:0;transform:translateY(12px);pointer-events:none;transition:.22s}#toast.show{opacity:1;transform:none}#toast.error{border-color:#733c43;background:#321d22;color:#ffc3c8}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.two-col,.being-hero{grid-template-columns:1fr}.three-col{grid-template-columns:repeat(2,1fr)}}@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{position:static;width:100%;height:auto;padding:14px}.brand{padding-bottom:12px}.sidebar nav{display:flex;overflow:auto}.nav-item{width:auto;white-space:nowrap}.sidebar-foot{display:none}.topbar{padding:18px;position:static}.health-pill{display:none}.top-actions .primary{display:none}main{padding:18px}.metrics{grid-template-columns:repeat(2,1fr)}.three-col{grid-template-columns:1fr}.focus-card h2{font-size:20px}.activity-steps{display:grid}.activity-steps span:not(:last-child):after{content:"↓"}.attention-item{grid-template-columns:9px 1fr}.attention-item .actions{grid-column:2;justify-content:flex-start}}
.project-head{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:6px}.project-summary{margin:10px 0 0;color:#c3cfd7;font-size:13px;line-height:1.6}.chat{display:flex;flex-direction:column;gap:12px}.chat-log{display:grid;gap:10px;max-height:460px;overflow:auto;padding-right:4px}.chat-msg{padding:12px 14px;border:1px solid #26343f;border-radius:12px;background:#0c1822}.chat-msg.HUMAN{border-color:#2d4a5e;background:#0e1d29}.chat-who{display:flex;align-items:center;gap:8px;margin-bottom:6px;color:#7d94a3;font-size:9px;font-weight:800;letter-spacing:.14em}.chat-text{margin:0;color:#dbe6ec;font-size:12px;line-height:1.65;white-space:pre-wrap}.chat-refs{margin-top:8px;color:#6f8493;font-size:10px;word-break:break-all}.chat-form{display:flex;gap:8px}.chat-form input{flex:1;min-width:0;padding:11px 13px;border:1px solid #2b414f;border-radius:10px;background:#08131c;color:var(--text)}.chat-form input:disabled{opacity:.6}.chat-note{margin:0;color:#6c8090;font-size:10px;line-height:1.6}.chat-note.error{color:var(--danger)}.chat-pending{display:flex;align-items:center;gap:8px;color:#8fb6a8;font-size:11px}.chat-pending i{width:12px;height:12px;border:2px solid #24404f;border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}.badge.READ_ONLY_REFUSED,.badge.OUT_OF_SCOPE,.badge.LLM_UNAVAILABLE,.badge.LLM_FAILED,.badge.LLM_INVALID,.badge.INFERENCE{border-color:#655332;background:#302617;color:#e7bd70}.badge.INSTRUCTION_EXECUTED{border-color:#2f5e46;background:#12291f;color:#7fd2a4}.badge.INSTRUCTION_REFUSED{border-color:#655332;background:#302617;color:#e7bd70}.badge.INSTRUCTION_FAILED{border-color:#6b3a3a;background:#2c1919;color:#e79090}.badge.NEEDS_ATTENTION{border-color:#655332;background:#302617;color:#e7bd70}.badge.IDLE{border-color:#3a4a56;background:#151f28;color:#a2b3bf}
.assistance-card{padding:20px;border:1px solid #745b35;border-radius:16px;background:linear-gradient(145deg,#211b13,#101a22);box-shadow:var(--shadow)}.assistance-card h3{margin:5px 0 8px;font-size:17px}.assistance-purpose{margin:0 0 15px;color:#dce6eb;font-size:13px}.assistance-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin:14px 0}.assistance-fact{padding:12px;border:1px solid #2b3943;border-radius:10px;background:#0b151e}.assistance-fact strong{display:block;margin-bottom:6px;color:#8da1ae;font-size:9px;letter-spacing:.1em;text-transform:uppercase}.assistance-fact p{margin:0;color:#c2cdd4;font-size:11px;line-height:1.55}.assistance-card .next-action{padding:12px 14px;border-left:3px solid var(--warn);background:#241e15;color:#efd8aa;font-size:12px;line-height:1.55}.attempt-list{margin:0;padding-left:18px;color:#aab9c2;font-size:11px;line-height:1.65}@media(max-width:760px){.assistance-grid{grid-template-columns:1fr}}
'''


APP_JS = r'''
const state={snapshot:null,view:"overview",project:null,orchestrator:null,token:sessionStorage.getItem("nexus-cockpit-token")||""};
const $=s=>document.querySelector(s);const app=$("#app");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const raw=v=>`<details><summary>Raw facts / audit detail</summary><pre class="raw">${esc(JSON.stringify(v,null,2))}</pre></details>`;
const when=v=>v?new Intl.DateTimeFormat("ja-JP",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v)):"—";
const badge=v=>`<span class="badge ${esc(v)}">${esc(v||"UNKNOWN")}</span>`;
const empty=(title,text="")=>`<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const section=(title,sub,body)=>`<section class="section"><div class="section-head"><div><h2>${esc(title)}</h2><p>${esc(sub||"")}</p></div></div>${body}</section>`;
const actionButton=(label,action,id="",tone="")=>`<button type="button" class="button small${tone?` ${tone}`:""}" data-action="${esc(action)}"${id?` data-id="${esc(id)}"`:""}>${esc(label)}</button>`;
function headers(){return state.token?{"Authorization":`Bearer ${state.token}`}:{}}
// crypto.randomUUID() exists only in a secure context, so it is missing when the
// Cockpit is opened over http:// on a LAN address. getRandomValues has no such
// restriction; Math.random is the last resort. These ids only have to be unique.
function uid(){const c=globalThis.crypto;if(c&&typeof c.randomUUID==="function")return c.randomUUID();const b=new Uint8Array(16);if(c&&typeof c.getRandomValues==="function")c.getRandomValues(b);else for(let i=0;i<16;i++)b[i]=Math.floor(Math.random()*256);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,"0"));return `${h.slice(0,4).join("")}-${h.slice(4,6).join("")}-${h.slice(6,8).join("")}-${h.slice(8,10).join("")}-${h.slice(10,16).join("")}`}
async function load(){try{const res=await fetch("/cockpit/api/snapshot",{headers:headers(),cache:"no-store"});if(res.status===401){showAuth();return}if(!res.ok)throw new Error(`Cockpit API ${res.status}`);state.snapshot=await res.json();updateChrome();render()}catch(err){app.innerHTML=empty("Cockpit snapshotを取得できません",err.message);$("#runtime-status").textContent="Offline";$("#sidebar-runtime").textContent="OFFLINE"}}
function showAuth(){const d=$("#auth-dialog");if(!d.open)d.showModal();$("#auth-error").textContent=""}
$("#auth-form").addEventListener("submit",e=>{e.preventDefault();state.token=$("#auth-token").value.trim();sessionStorage.setItem("nexus-cockpit-token",state.token);$("#auth-dialog").close();load()});
function updateChrome(){const s=state.snapshot;$("#runtime-status").textContent=s.overview.runtime.status;$("#sidebar-runtime").textContent=`RUNTIME ${s.overview.runtime.status}`;$("#last-update").textContent=`Updated ${when(s.generated_at)}`}
const titles={overview:["CURRENT SITUATION","Overview"],knowledge:["KNOWLEDGE RUNTIME","World"],activity:["CAUSAL HISTORY","Activity"],orchestrator:["PROJECT ORCHESTRATOR","Projects"],system:["RUNTIME HEALTH","System"]};
document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>{state.view=b.dataset.view;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x===b));const t=titles[state.view];$("#view-eyebrow").textContent=t[0];$("#view-title").textContent=t[1];render()}));$("#refresh").onclick=load;
function metric(label,value,sub="",tone=""){return `<div class="metric"><div class="label"><span>${esc(label)}</span></div><strong class="${tone}">${esc(value)}</strong><small>${esc(sub)}</small></div>`}
function render(){if(!state.snapshot)return;({overview:renderOverview,knowledge:renderKnowledge,activity:renderActivity,orchestrator:renderOrchestrator,system:renderSystem}[state.view]||renderOverview)()}
function attention(items){if(!items.length)return empty("判断を必要とする項目はありません","Runtimeは次のEventを待っています。");return `<div class="attention-list">${items.map(x=>x.kind==="capability_assistance"?capabilityAssistanceCard(x.assistance,true):`<article class="attention-item ${x.severity}"><span class="signal"></span><div><h3>${esc(x.title)}</h3><p>${esc(x.message)}</p>${raw(x.raw)}</div><div class="actions">${attentionActions(x)}</div></article>`).join("")}</div>`}
function attentionActions(x){if(x.kind==="project_blocked"||x.kind==="resource_request")return actionButton("Projectを開く","open-orchestrator-project",x.target_id,"primary");if(x.kind==="task_candidate")return `${actionButton("実行","task-candidate-approve",x.target_id,"primary")}${actionButton("無視","task-candidate-reject",x.target_id,"danger")}${actionButton("修正","task-candidate-amend",x.target_id)}`;return""}
function activityCard(a){return `<article class="activity-card"><span class="result">${badge(a.result.replace(" ","_"))}</span><h3>${esc(a.title)}</h3><p class="eyebrow">${when(a.updated_at)}</p><div class="activity-steps">${a.steps.map(s=>`<span>${esc(s)}</span>`).join("")}</div>${raw(a.details)}</article>`}
function renderOverview(){const s=state.snapshot,o=s.overview,c=o.counts;app.innerHTML=`<div class="grid metrics">${metric("Runtime",o.runtime.status,"Durable runtime")}${metric("LLM",o.llm.status,o.llm.model||"Not configured")}${metric("Projects",c.active_projects,"Live")}${metric("Reviews",c.pending_reviews,"Waiting for human",c.pending_reviews?"tone-warning":"")}${metric("Questions",c.open_questions,"Agent asks",c.open_questions?"tone-warning":"")}${metric("Errors / Warnings",`${c.errors} / ${c.warnings}`,"Needs attention",c.errors?"tone-error":c.warnings?"tone-warning":"")}</div><section class="focus-card"><p class="eyebrow">CURRENT FOCUS · ${esc(o.focus.disposition)}</p><h2>${esc(o.focus.label)}</h2><div class="focus-meta"><span>${esc(o.focus.source_event_type)}</span><span>•</span><span>${when(o.focus.updated_at)}</span></div></section><div class="grid two-col"><div>${section("Needs Attention","ProjectとKnowledgeが人の判断を待っている項目",attention(s.needs_attention))}</div><div>${section("Projects","Project Orchestratorが進めている仕事",`<div class="stack">${(s.orchestrator.projects||[]).filter(p=>!["COMPLETED","CANCELLED","FAILED"].includes(p.status)).slice(0,5).map(orchestratorCard).join("")||empty("進行中のProjectなし")}</div>`)}</div></div>${section("Recent Activity","Project・Knowledgeを支えるdurable activity",`<div class="timeline">${s.activities.slice(0,6).map(activityCard).join("")||empty("Activityはまだありません")}</div>`)}`}
function renderActivity(){app.innerHTML=section("Activity Timeline","Process names are hidden until you open internal details",`<div class="timeline">${state.snapshot.activities.map(activityCard).join("")||empty("Activityはまだありません")}</div>`)}
async function api(path,options){const res=await fetch(path,{cache:"no-store",...options,headers:{...headers(),"Content-Type":"application/json"}});if(res.status===401){showAuth();throw new Error("認証が必要です")}const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.error||`Request failed (${res.status})`);return body}
const projectPath=(id,suffix)=>`/projects/${encodeURIComponent(id)}/${suffix}`;
function chatMessage(m){const who=m.role==="HUMAN"?"YOU":"NEXUS SEED",marks=[m.role!=="HUMAN"&&m.status!=="ANSWERED"?badge(m.status):"",m.certainty&&m.certainty!=="FACT"?badge(m.certainty):""].join("");return `<article class="chat-msg ${esc(m.role)}"><div class="chat-who"><span>${esc(who)}</span><span>${when(m.created_at)}</span>${marks}</div><p class="chat-text">${esc(m.text)}</p>${m.references?.length?`<div class="chat-refs">参照: ${m.references.map(esc).join(", ")}</div>`:""}</article>`}
const orchestratorPath=id=>`/cockpit/api/orchestrator/projects/${encodeURIComponent(id)}`;
async function openOrchestratorProject(id){state.view="orchestrator";state.orchestrator={id,detail:null,chat:null,messageKey:null,lastAsked:null,error:""};render();try{const[detail,chat]=await Promise.all([api(orchestratorPath(id)),api(projectPath(id,"chat")).catch(()=>null)]);Object.assign(state.orchestrator,{detail,chat})}catch(err){state.orchestrator.error=err.message}render()}
function closeOrchestratorProject(){state.orchestrator=null;render()}
async function orchestratorAction(action,body){const o=state.orchestrator;if(!o||o.pending)return;o.pending=true;o.error="";render();try{await api(`${orchestratorPath(o.id)}/${action}`,{method:"POST",body:JSON.stringify(body)});const[detail,chat]=await Promise.all([api(orchestratorPath(o.id)),api(projectPath(o.id,"chat")).catch(()=>o.chat)]);Object.assign(o,{detail,chat});await load()}catch(err){o.error=err.message}o.pending=false;render();}
function newRequestId(){return crypto.randomUUID?crypto.randomUUID():`r-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function unblockOrchestrator(){orchestratorAction("unblock",{note:"人が対応しました"})}
// Resource要求は「詰まっている」とは別物なので、ブロック解除ではなく
// 何を渡すかを人が決めて同じTaskを続ける。
function resourceBlocker(){const d=state.orchestrator&&state.orchestrator.detail;if(!d)return null;return d.blockers.find(b=>b.kind==="NEED_RESOURCE")||null}
function grantOrchestratorResource(){const b=resourceBlocker();const detail=(b&&b.detail)||{};const uri=prompt("渡すResourceのURI (file:<path> / resource:<uri> / knowledge:<id>)",detail.uri||"");if(!uri||!uri.trim())return;const writable=confirm("書き込みも許可しますか？ OK=read_write / キャンセル=read");const copy=confirm("OK=workspaceへコピー（原本は変更されません） / キャンセル=元のpathを直接参照");orchestratorAction("grant",{uri:uri.trim(),access:writable?"read_write":"read",delivery:copy?"copy":"reference",reason:"Cockpitで人が許可"})}
function agentLine(a){if(!a)return "Agent未割り当て";const parts=[`${a.agent_id} (${a.runtime})`,a.status];if(a.assignment)parts.push(`assignment ${a.assignment.status}`);if(a.unavailable)parts.push(`unreachable: ${a.unavailable.reason}`);return parts.join(" · ")}
function orchestratorCard(p){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(p.id)}</p><h3>${esc(p.goal)}</h3></div>${badge(p.status)}</div><p>${esc(p.summary||"Agentからの報告はまだありません")}</p>${p.blockers.length?`<div class="capabilities">${p.blockers.map(b=>`<span class="badge error">${esc(b.kind)}</span>`).join("")}</div>`:""}<div class="meta"><span>Priority ${esc(p.priority)}</span><span>${esc(agentLine(p.agent))}</span><span>Tasks ${esc(p.task_count)}</span><span>${when(p.updated_at)}</span></div><div class="actions">${actionButton("開く","open-orchestrator-project",p.id,"primary")}</div></article>`}
function orchestratorMessage(m){return `<li>${when(m.timestamp)} · ${esc(m.direction)} · ${esc(m.type)}${m.payload&&m.payload.summary?` — ${esc(m.payload.summary)}`:""}${m.payload&&m.payload.reason?` — ${esc(m.payload.reason)}`:""}</li>`}
function orchestratorBlocker(b){return `<li>${esc(b.kind)} · ${esc(b.reason)}${b.resolved_at?` — 解消 ${when(b.resolved_at)}（${esc(b.resolved_by||"")}）`:" — 現在も停止中"}</li>`}
async function sendProjectMessage(message,act=false){const o=state.orchestrator;if(!o||o.pending||!message.trim())return;if(!o.messageKey)o.messageKey=newRequestId();o.pending=true;o.error="";render();try{const out=await api(projectPath(o.id,"message"),{method:"POST",body:JSON.stringify({message:message.trim(),request_id:o.messageKey,act})});o.messageKey=null;o.lastAsked=out.kind==="ASKED"?message.trim():null;const[detail,chat]=await Promise.all([api(orchestratorPath(o.id)),api(projectPath(o.id,"chat"))]);Object.assign(o,{detail,chat});await load()}catch(err){o.error=err.message}o.pending=false;render();const input=$("#project-message-input");if(input)input.focus()}
function resendAsInstruction(){const o=state.orchestrator;if(o&&o.lastAsked)sendProjectMessage(o.lastAsked,true)}
function projectThreadPanel(){const o=state.orchestrator,d=o.detail,chat=o.chat,messages=chat?.messages||[];const note=chat&&chat.llm&&!chat.llm.enabled?"LLM未接続のため、意味では判断できません。明らかな指示以外は説明で返します。":d.agent?"質問には答え、指示はAgentに渡します。独立した問題と判断された場合は子Projectになります。":"Agent未割り当てです。指示すると割り当てを試みます。";return `<section class="panel panel-pad chat"><p class="eyebrow">PROJECT THREAD</p><div class="chat-log">${messages.length?messages.map(chatMessage).join(""):empty("まだやり取りはありません","質問も指示も同じ欄に書いてください。")}</div>${o.pending?'<div class="chat-pending"><i></i><span>処理しています…</span></div>':""}<form id="project-message-form" class="chat-form"><input id="project-message-input" name="message" autocomplete="off" placeholder="今どうなってる？ / 地域別の内訳も出して"${o.pending?" disabled":""}><button class="button primary" type="submit"${o.pending?" disabled":""}>送る</button></form>${o.lastAsked?`<div class="actions">${actionButton("指示として渡す","resend-as-instruction")}</div><p class="chat-note">説明で返しましたが、実行させたい場合はこちら。</p>`:""}${o.error?`<p class="chat-note error">${esc(o.error)}</p>`:""}<p class="chat-note">${esc(note)}</p></section>`}
function orchestratorDetail(){const o=state.orchestrator,d=o.detail;const head=`<div class="project-head"><div><p class="eyebrow">${esc(o.id)}</p><h2>${esc(d?d.goal:o.id)}</h2></div><div class="actions">${actionButton("← Projects","close-orchestrator-project")}${actionButton("再読み込み","open-orchestrator-project",o.id)}</div></div>${o.error?`<p class="chat-note error">${esc(o.error)}</p>`:""}`;if(!d)return `${head}<div class="panel panel-pad"><div class="chat-pending"><i></i><span>Projectを読み込んでいます…</span></div></div>`;return `${head}<section class="panel panel-pad"><div class="card-top"><div><p class="eyebrow">GOAL</p><h3>${esc(d.goal)}</h3></div>${badge(d.status)}</div><p class="project-summary">${esc(d.summary||"Agentからの報告はまだありません")}</p><div class="meta"><span>Priority ${esc(d.priority)}</span><span>${esc(agentLine(d.agent))}</span><span>Updated ${when(d.updated_at)}</span></div></section>${section("Thread","質問にも指示にもこの欄ひとつ。NEXUS SEEDがどちらかを判断します",projectThreadPanel())}${section("Blockers",`${d.blockers.length} 件が現在の停止理由`,`<article class="panel panel-pad"><ul class="attempt-list">${d.blocker_history.map(orchestratorBlocker).join("")||"<li>Blockerは記録されていません</li>"}</ul>${d.blockers.length?`<div class="actions">${d.blockers.some(b=>b.kind==="NEED_RESOURCE")?actionButton("Resourceを許可して続行","grant-orchestrator-resource",o.id,"primary"):""}${actionButton("ブロック解除してAgentに戻す","unblock-orchestrator-project",o.id)}</div>`:""}</article>`)}${section("Tasks",`${d.tasks.length} 件の追加指示`,`<article class="panel panel-pad"><ul class="attempt-list">${d.tasks.map(x=>`<li>${when(x.created_at)} · ${esc(x.description)}</li>`).join("")||"<li>追加指示はありません</li>"}</ul></article>`)}${section("A2A Channel","NEXUS SEEDとProject Agentのやり取り",`<article class="panel panel-pad"><ul class="attempt-list">${d.messages.map(orchestratorMessage).join("")||"<li>まだ記録がありません</li>"}</ul>${raw(d.agent)}</article>`)}`}
function renderOrchestrator(){if(state.orchestrator){app.innerHTML=orchestratorDetail();return}const o=state.snapshot.orchestrator||{projects:[],counts:{}};const list=o.projects||[];app.innerHTML=section("Projects",`${list.length}件のProjectをProject Orchestratorが管理しています`,`<div class="card-grid">${list.map(orchestratorCard).join("")||empty("Projectはまだありません","requestを送るとProjectが作られます。")}</div>`)}
function knowledgeContent(x){return typeof x.content==="string"?esc(x.content):`<pre>${esc(JSON.stringify(x.content,null,2))}</pre>`}
function knowledgeProposal(p){const m=p.metadata||{},buttons=p.status==="PENDING_REVIEW"?`${actionButton("Approve","knowledge-proposal-approve",p.knowledge_id,"primary")}${actionButton("Reject","knowledge-proposal-reject",p.knowledge_id,"danger")}`:"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(p.knowledge_id)}</p><h3>${knowledgeContent(p)}</h3></div>${badge(p.status||"UNKNOWN")}</div><p>${esc(m.reason||"")}</p><div class="meta"><span>Risk ${esc(m.risk||"?")}</span><span>Confidence ${esc(m.confidence??"?")}</span><span>${m.read_only?"Read only":"May act"}</span></div><div class="actions">${buttons}${m.project_id?actionButton("Projectを開く","open-orchestrator-project",m.project_id):""}</div>${raw({evidence_ids:m.evidence_ids||[],policy_reason:m.policy_reason,expected_artifacts:m.expected_artifacts||[]})}</article>`}
function worldFact(f){return `<article class="card"><p class="eyebrow">${esc(f.entity)}</p><h3>${esc(f.attribute)}</h3><p>${esc(typeof f.value==="string"?f.value:JSON.stringify(f.value))}</p><div class="meta"><span>${esc(f.knowledge_id)}</span><span>Confidence ${esc(f.confidence??"?")}</span></div></article>`}
function knowledgeArtifact(a){const pending=a.status==="PENDING_REVIEW",buttons=pending?`${actionButton("承認","knowledge-artifact-approve",a.knowledge_id,"primary")}${actionButton("差し戻し","knowledge-artifact-reject",a.knowledge_id,"danger")}`:"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(a.metadata?.name||a.kind)}</p><h3>${esc(a.knowledge_id)}</h3></div>${badge(a.status||"RECORDED")}</div><div>${knowledgeContent(a)}</div><div class="meta"><span>${when(a.recorded_at)}</span><span>${esc(a.metadata?.project_id||"")}</span></div><div class="actions">${buttons}${a.metadata?.project_id?actionButton("Projectを開く","open-orchestrator-project",a.metadata.project_id):""}</div>${raw(a.metadata)}</article>`}
function completionReview(r){const pending=r.status==="PENDING_REVIEW",buttons=pending?`${actionButton("すべて承認","knowledge-completion-approve",r.knowledge_id,"primary")}${actionButton("差し戻し","knowledge-completion-reject",r.knowledge_id,"danger")}`:"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">COMPLETION REVIEW</p><h3>${knowledgeContent(r)}</h3></div>${badge(r.status||"PENDING_REVIEW")}</div><div class="meta"><span>${esc((r.metadata?.artifact_ids||[]).length)} Artifacts</span><span>${when(r.recorded_at)}</span></div><div class="actions">${buttons}${r.metadata?.project_id?actionButton("Projectを開く","open-orchestrator-project",r.metadata.project_id):""}</div>${raw(r.metadata)}</article>`}
function knowledgeQuestion(q){const open=q.status==="OPEN";return `<article class="card"><div class="card-top"><h3>${knowledgeContent(q)}</h3>${badge(q.status||"OPEN")}</div><div class="meta"><span>${esc(q.metadata?.project_id||"")}</span><span>${when(q.recorded_at)}</span></div><div class="actions">${open?actionButton("回答する","knowledge-question-answer",q.knowledge_id,"primary"):""}</div>${raw(q.metadata)}</article>`}
function knowledgeEntity(e){const open=e.status==="UNRESOLVED";return `<article class="card"><div class="card-top"><div><p class="eyebrow">UNKNOWN ENTITY</p><h3>${knowledgeContent(e)}</h3></div>${badge(e.status||"UNRESOLVED")}</div><p>Suggested: ${esc(e.metadata?.suggested_entity_id||"なし")}</p><div class="actions">${open?actionButton("同一Entityとして確認","knowledge-entity-confirm",e.knowledge_id,"primary")+actionButton("別Entity","knowledge-entity-separate",e.knowledge_id):""}</div>${raw(e.metadata)}</article>`}
function knowledgePrinciple(p){const support=p.support_count||0,against=p.counterexample_count||0,tone=against?"tone-warning":"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">PRINCIPLE · ${esc(p.knowledge_id)}</p><h3>${knowledgeContent(p)}</h3></div>${badge(p.status||"candidate")}</div>${p.scope?`<p>Scope: ${esc(p.scope)}</p>`:""}<div class="meta"><span class="${tone}">支持 ${esc(support)} · 反例 ${esc(against)}</span><span>rev ${esc(p.revision)}</span><span>${when(p.recorded_at)}</span></div>${raw({derived_from:p.derived_from||[],evidence_for:p.evidence_for||[],evidence_against:p.evidence_against||[]})}</article>`}
function knowledgeMemory(m){return `<article class="card"><div class="card-top"><div><p class="eyebrow">MEMORY · ${esc(m.metadata?.about||"（主題なし）")}</p><h3>${esc(m.knowledge_id)}</h3></div>${m.status?badge(m.status):""}</div><div>${knowledgeContent(m)}</div><div class="meta"><span>${esc((m.derived_from||[]).length)}件を統合</span><span>gen ${esc(m.metadata?.generation??"?")}</span><span>${when(m.recorded_at)}</span></div>${(m.metadata?.unresolved||[]).length?`<p class="chat-note">未解決: ${esc((m.metadata.unresolved||[]).join(" / "))}</p>`:""}${raw({derived_from:m.derived_from||[]})}</article>`}
function taskCandidate(c){const m=c.metadata||{},pending=c.status==="PENDING_REVIEW",buttons=pending?`${actionButton("実行","task-candidate-approve",c.knowledge_id,"primary")}${actionButton("無視","task-candidate-reject",c.knowledge_id,"danger")}${actionButton("修正","task-candidate-amend",c.knowledge_id)}`:"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(m.suggested_assignee_type||"UNKNOWN")}</p><h3>${knowledgeContent(c)}</h3></div>${badge(c.status||"UNKNOWN")}</div><p>${esc(m.reason||"")}</p><div class="meta"><span>Confidence ${esc(m.confidence??"?")}</span>${m.amended_by?`<span>${esc(m.amended_by)}が修正</span>`:""}${m.project_id?`<span>Project ${esc(m.project_id)}</span>`:""}</div><div class="actions">${buttons}${m.project_id?actionButton("Projectを開く","open-orchestrator-project",m.project_id):""}</div>${raw({evidence:m.evidence||[],amended_from:m.amended_from,review_note:m.review_note,assessment_id:m.assessment_id})}</article>`}
function contextDocument(role,d){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(role)}.md</p><h3>rev ${esc(d.revision)}</h3></div></div><pre class="raw">${esc(d.text)}</pre></article>`}
function knowledgeAssessment(a){const c=(a.metadata||{}).counts||{};return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(a.knowledge_id)}</p><h3>${esc(when(a.recorded_at))}</h3></div></div><div class="meta"><span>用語 ${esc(c.terminology_issues??0)}</span><span>矛盾 ${esc(c.contradictions??0)}</span><span>Gap ${esc(c.goal_gaps??0)}</span><span>不明 ${esc(c.unknowns??0)}</span><span>Task候補 ${esc(c.task_candidates??0)}</span></div>${raw(a.content)}</article>`}
function knowledgeInbox(x){return `<article class="card"><div class="card-top"><div><p class="eyebrow">${esc(x.kind)} · ${esc(x.knowledge_id)}</p><h3>${esc(x.source?.type||"unknown")}</h3></div>${x.status?badge(x.status):""}</div><div>${knowledgeContent(x)}</div><div class="meta"><span>${when(x.recorded_at)}</span><span>${esc(x.source?.ref||"")}</span></div>${raw(x.metadata)}</article>`}
function observationSource(s){const action=s.enabled?"disable":"enable",label=s.enabled?"停止":"再開",kind=s.kind==="folder_status"?"FOLDER STATUS":"SYSTEM SNAPSHOT",where=s.config&&s.config.path?`<p>${esc(s.config.path)}</p>`:"";return `<article class="card"><div class="card-top"><div><p class="eyebrow">${kind}</p><h3>${esc(s.name)}</h3></div>${badge(s.enabled?"ENABLED":"DISABLED")}</div>${where}<div class="meta"><span>${(s.fields||[]).map(esc).join(" · ")}</span><span>${esc(s.poll_interval_seconds)}秒ごと</span><span>最終確認 ${when(s.last_checked_at)}</span></div>${s.last_error?`<p class="chat-note error">${esc(s.last_error)}</p>`:""}<div class="actions">${actionButton("今すぐ観測","observation-source-poll",s.id,"primary")}${actionButton(label,`observation-source-${action}`,s.id)}</div></article>`}
function renderKnowledge(){const k=state.snapshot.knowledge||{enabled:false,world:{facts:[],conflicts:[]},inbox:[],proposals:[],artifacts:[],completion_reviews:[],questions:[],entities:[],principles:[],memories:[],context:{},assessments:[],task_candidates:[],observation_sources:[]};if(!k.enabled){app.innerHTML=empty("Knowledge Loopは無効です","NEXUS_SEED_KNOWLEDGE_LOOP_ENABLEDを確認してください。");return}const pending=k.proposals.filter(x=>x.status==="PENDING_REVIEW").length,pendingArtifacts=k.artifacts.filter(x=>x.status==="PENDING_REVIEW").length,pendingCompletions=k.completion_reviews.filter(x=>x.status==="PENDING_REVIEW").length,openQuestions=k.questions.filter(x=>x.status==="OPEN").length,unknown=k.entities.filter(x=>x.status==="UNRESOLVED").length,sources=k.observation_sources||[],principles=k.principles||[],memories=k.memories||[],mature=principles.filter(x=>["supported","validated"].includes(x.status)).length,candidates=k.task_candidates||[],pendingCandidates=candidates.filter(x=>x.status==="PENDING_REVIEW").length,assessments=k.assessments||[],contextDocs=Object.entries(k.context||{});const capture=`<form id="knowledge-observation-form" class="chat-form"><input id="knowledge-observation-input" autocomplete="off" placeholder="観測した事実や状況を入力"><button class="button primary" type="submit">記録</button></form><p class="chat-note">外部入力としてIngressを通り、出典付きKnowledgeになります。</p>`,folderForm=`<form id="observation-source-form" class="panel panel-pad"><input type="hidden" name="kind" value="folder_status"><div class="chat-form"><input name="name" autocomplete="off" placeholder="観測元の名前" required><input name="path" autocomplete="off" placeholder="フォルダの絶対パス" required><input name="interval" type="number" min="1" value="300" aria-label="観測間隔（秒）"><button class="button primary" type="submit">登録して観測</button></div><div class="capabilities"><label><input type="checkbox" name="fields" value="file_count" checked> ファイル数</label><label><input type="checkbox" name="fields" value="total_bytes" checked> 合計サイズ</label><label><input type="checkbox" name="fields" value="oldest_change" checked> 最古の更新日時</label><label><input type="checkbox" name="fields" value="newest_change"> 最新の更新日時</label><label><input type="checkbox" name="fields" value="by_extension"> 拡張子ごとの件数</label></div><p class="chat-note">読むのはフォルダの目録（名前・サイズ・更新日時）だけで、ファイルを開くことはありません。「溜まっている」という状況を観測します。</p></form>`,sourceForm=`<form id="observation-source-form" class="panel panel-pad"><input type="hidden" name="kind" value="system_snapshot"><div class="chat-form"><input name="name" autocomplete="off" placeholder="観測元の名前" required><input name="interval" type="number" min="1" value="60" aria-label="観測間隔（秒）"><button class="button primary" type="submit">登録して観測</button></div><div class="capabilities"><label><input type="checkbox" name="fields" value="platform" checked> OS</label><label><input type="checkbox" name="fields" value="hostname"> ホスト名</label><label><input type="checkbox" name="fields" value="cpu" checked> CPU</label><label><input type="checkbox" name="fields" value="memory" checked> メモリ</label><label><input type="checkbox" name="fields" value="data_disk" checked> NEXUS_SEEDデータ領域</label></div><p class="chat-note">選択した固定項目だけを読みます。ファイル内容・実行中プロセス・ユーザーディレクトリは走査しません。</p></form>`;app.innerHTML=`<div class="grid metrics">${metric("World facts",k.world.facts.length,"Current projection")}${metric("Sources",sources.filter(x=>x.enabled).length,`${sources.length} configured`)}${metric("Proposals",pending,"Waiting review",pending?"tone-warning":"")}${metric("Deliverables",pendingArtifacts,"Waiting approval",pendingArtifacts?"tone-warning":"")}${metric("Questions",openQuestions,"Agent asks",openQuestions?"tone-warning":"")}${metric("Unknown entities",unknown,"Need identity",unknown?"tone-warning":"")}${metric("Principles",mature,`${principles.length} learned`)}${metric("Task候補",pendingCandidates,"Waiting decision",pendingCandidates?"tone-warning":"")}</div>${section("Bootstrap Context","terms / goals / situation — 人が書いた原文をそのまま保持します",`<div class="card-grid">${contextDocs.map(([role,d])=>contextDocument(role,d)).join("")||empty("context/ にはまだ何も書かれていません")}</div>`)}${section("Task候補",`${pendingCandidates} 件が判断待ち`,`<p class="chat-note">SituationAssessmentからの提案です。実行されるのは人が「実行」を押したものだけで、既存の入口を通ってProjectまたはTaskになります。</p><div class="card-grid">${candidates.map(taskCandidate).join("")||empty("Task候補はありません")}</div>`)}${section("Situation Assessments",`${assessments.length} readings`,`<div class="card-grid">${assessments.map(knowledgeAssessment).join("")||empty("まだ評価していません")}</div>`)}${section("Observation Sources","ユーザーが許可した環境情報だけを継続観測",`${sourceForm}${folderForm}<div class="card-grid">${sources.map(observationSource).join("")||empty("観測元は未登録です")}</div>`)}${section("Record Observation","手動で世界の状況を知らせる",`<article class="panel panel-pad">${capture}</article>`)}${section("Project Proposals",`${k.proposals.length} durable proposals`,`<div class="card-grid">${k.proposals.map(knowledgeProposal).join("")||empty("Project提案はありません")}</div>`)}${section("Completion Reviews",`${pendingCompletions} waiting`,`<div class="card-grid">${k.completion_reviews.map(completionReview).join("")||empty("完了確認待ちはありません")}</div>`)}${section("World View",`${k.world.facts.length} facts · ${k.world.conflicts.length} conflicts`,`<div class="card-grid">${k.world.facts.map(worldFact).join("")||empty("構造化されたWorld factはまだありません")}</div>${k.world.conflicts.length?raw(k.world.conflicts):""}`)}${section("Principles",`${mature} mature · ${principles.length} total`,`<p class="chat-note">経験から一般化した予測モデルです。真理ではありません。candidateは反例検証を通っていないため判断には使われません。</p><div class="card-grid">${principles.map(knowledgePrinciple).join("")||empty("まだ原則を獲得していません")}</div>`)}${section("Consolidated Memory",`${memories.length} memories`,`<p class="chat-note">元のKnowledgeは削除されず残ります。</p><div class="card-grid">${memories.map(knowledgeMemory).join("")||empty("統合された記憶はまだありません")}</div>`)}${section("Questions",`${openQuestions} unanswered`,`<div class="card-grid">${k.questions.map(knowledgeQuestion).join("")||empty("Agentからの質問はありません")}</div>`)}${section("Unknown Entities",`${unknown} unresolved`,`<div class="card-grid">${k.entities.map(knowledgeEntity).join("")||empty("未解決Entityはありません")}</div>`)}${section("Artifacts",`${k.artifacts.length} recorded`,`<div class="card-grid">${k.artifacts.map(knowledgeArtifact).join("")||empty("成果物はまだありません")}</div>`)}${section("Knowledge Inbox",`Recent ${k.inbox.length}`,`<div class="card-grid">${k.inbox.map(knowledgeInbox).join("")||empty("Knowledgeはまだありません")}</div>`)}`}
function renderSystem(){const s=state.snapshot;app.innerHTML=`<div class="grid metrics">${metric("Runtime",s.overview.runtime.status,"Request reached live runtime")}${metric("Projects","ON","Primary orchestration")}${metric("Knowledge",s.knowledge.enabled?"ON":"OFF","Autonomous loop")}${metric("LLM",s.overview.llm.status,s.overview.llm.model||"")}${metric("Raw trace","AVAILABLE","Audit history retained")}</div>${section("Delivery Health","Durable Event delivery",`<article class="panel panel-pad">${raw(s.system.delivery)}</article>`)}${section("Current Process Status","Read-only projection",`<article class="panel panel-pad">${raw(s.system.process_counts)}</article>`)}${section("Recent Failures","Human explanation appears in Needs Attention; raw facts stay here",`<div class="card-grid">${s.system.recent_failures.map(x=>`<article class="card"><h3>${esc(x.definition)}</h3>${badge(x.status)}${raw(x)}</article>`).join("")||empty("Current unresolved failureなし")}</div>`)}`}
async function decideKnowledgeProposal(id,decision){try{await api(`/cockpit/api/knowledge/proposals/${encodeURIComponent(id)}/${decision}`,{method:"POST",body:"{}"});toast(`Proposalを${decision}しました`);await load()}catch(err){toast(err.message,true)}}
async function decideKnowledgeArtifact(id,decision){const note=decision==="reject"?prompt("差し戻し理由を入力してください"):"";if(decision==="reject"&&!note?.trim())return;try{await api(`/cockpit/api/knowledge/artifacts/${encodeURIComponent(id)}/${decision}`,{method:"POST",body:JSON.stringify({note:note?.trim()||""})});toast(decision==="approve"?"成果物を承認しました":"成果物を同じAgentへ差し戻しました");await load()}catch(err){toast(err.message,true)}}
async function decideKnowledgeCompletion(id,decision){const note=decision==="reject"?prompt("差し戻し理由を入力してください"):"";if(decision==="reject"&&!note?.trim())return;try{await api(`/cockpit/api/knowledge/completion-reviews/${encodeURIComponent(id)}/${decision}`,{method:"POST",body:JSON.stringify({note:note?.trim()||""})});toast(decision==="approve"?"Projectの完了を承認しました":"完了報告を同じAgentへ差し戻しました");await load()}catch(err){toast(err.message,true)}}
async function answerKnowledgeQuestion(id){const answer=prompt("Agentへの回答を入力してください");if(!answer?.trim())return;try{await api(`/cockpit/api/knowledge/questions/${encodeURIComponent(id)}/answer`,{method:"POST",body:JSON.stringify({answer:answer.trim()})});toast("回答をKnowledgeへ記録しました");await load()}catch(err){toast(err.message,true)}}
async function decideKnowledgeEntity(id,decision){let canonical_id=null;if(decision==="confirm"){canonical_id=prompt("同一と確認するcanonical Entity IDを入力してください");if(!canonical_id?.trim())return}try{await api(`/cockpit/api/knowledge/entities/${encodeURIComponent(id)}/${decision}`,{method:"POST",body:JSON.stringify({canonical_id:canonical_id?.trim()||null})});toast("Entity identityを記録しました");await load()}catch(err){toast(err.message,true)}}
async function decideTaskCandidate(id,decision){let body={};if(decision==="amend"){const text=prompt("このTaskをどう書き換えますか");if(!text?.trim())return;body={description:text.trim(),note:prompt("なぜ書き換えたか（任意）")||""}}else if(decision==="reject"){body={note:prompt("なぜやらないか（任意）")||""}}try{await api(`/cockpit/api/knowledge/task-candidates/${encodeURIComponent(id)}/${decision}`,{method:"POST",body:JSON.stringify(body)});toast(decision==="approve"?"Taskを実行に回しました":decision==="reject"?"Task候補を無視しました":"Task候補を修正しました");await load()}catch(err){toast(err.message,true)}}
async function recordKnowledge(text){if(!text.trim())return;try{await api("/cockpit/api/knowledge",{method:"POST",body:JSON.stringify({text:text.trim(),source_event_key:newRequestId()})});toast("観測をKnowledgeへ記録しました");await load()}catch(err){toast(err.message,true)}}
async function observationSourceAction(id,action){try{await api(`/cockpit/api/knowledge/sources/${encodeURIComponent(id)}/${action}`,{method:"POST",body:"{}"});toast(action==="poll"?"観測しました":action==="enable"?"観測を再開しました":"観測を停止しました");await load()}catch(err){toast(err.message,true)}}
async function createObservationSource(form){const data=new FormData(form),fields=data.getAll("fields"),kind=String(data.get("kind")||"system_snapshot"),path=String(data.get("path")||"").trim();try{await api("/cockpit/api/knowledge/sources",{method:"POST",body:JSON.stringify({name:String(data.get("name")||"").trim(),fields,kind,path:path||null,poll_interval_seconds:Number(data.get("interval")||60)})});toast("観測元を登録しました");await load()}catch(err){toast(err.message,true)}}
app.addEventListener("click",event=>{const button=event.target.closest("button[data-action]");if(!button||!app.contains(button))return;const action=button.dataset.action,id=button.dataset.id||"";if(action.startsWith("observation-source-"))observationSourceAction(id,action.replace("observation-source-",""));else if(action==="knowledge-proposal-approve")decideKnowledgeProposal(id,"approve");else if(action==="knowledge-proposal-reject")decideKnowledgeProposal(id,"reject");else if(action==="knowledge-artifact-approve")decideKnowledgeArtifact(id,"approve");else if(action==="knowledge-artifact-reject")decideKnowledgeArtifact(id,"reject");else if(action==="knowledge-completion-approve")decideKnowledgeCompletion(id,"approve");else if(action==="knowledge-completion-reject")decideKnowledgeCompletion(id,"reject");else if(action==="task-candidate-approve")decideTaskCandidate(id,"approve");else if(action==="task-candidate-reject")decideTaskCandidate(id,"reject");else if(action==="task-candidate-amend")decideTaskCandidate(id,"amend");else if(action==="knowledge-question-answer")answerKnowledgeQuestion(id);else if(action==="knowledge-entity-confirm")decideKnowledgeEntity(id,"confirm");else if(action==="knowledge-entity-separate")decideKnowledgeEntity(id,"separate");else if(action==="resend-as-instruction")resendAsInstruction();else if(action==="open-orchestrator-project")openOrchestratorProject(id);else if(action==="close-orchestrator-project")closeOrchestratorProject();else if(action==="unblock-orchestrator-project")unblockOrchestrator();else if(action==="grant-orchestrator-resource")grantOrchestratorResource()});
app.addEventListener("submit",event=>{const projectForm=event.target.closest("#project-message-form"),knowledgeForm=event.target.closest("#knowledge-observation-form"),sourceForm=event.target.closest("#observation-source-form");if(projectForm&&app.contains(projectForm)){event.preventDefault();const input=projectForm.querySelector("input"),text=input?input.value:"";if(input)input.value="";sendProjectMessage(text);return}if(sourceForm&&app.contains(sourceForm)){event.preventDefault();createObservationSource(sourceForm);return}if(knowledgeForm&&app.contains(knowledgeForm)){event.preventDefault();const input=knowledgeForm.querySelector("input"),text=input?input.value:"";if(input)input.value="";recordKnowledge(text)}});
function toast(message,error=false){const t=$("#toast");t.textContent=message;t.className=error?"show error":"show";setTimeout(()=>t.className="",3200)}
load();
'''


__all__ = ["APP_JS", "INDEX_HTML", "STYLES_CSS"]
